<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { api, errorMessage } from '../api';
type User={_id:string;firstName?:string;lastName?:string;name?:string;email:string;role:string;status?:string;lastLoginAt?:string};
const users=ref<User[]>([]), error=ref(''), query=ref(''), dialog=ref(false);
const form=ref({firstName:'',lastName:'',email:'',password:'',role:'RECEPTIONIST',status:'ACTIVE'});
const filtered=computed(()=>users.value.filter(user => `${user.firstName||user.name||''} ${user.lastName||''} ${user.email}`.toLowerCase().includes(query.value.toLowerCase())));
async function load(){try{users.value=(await api.get('/users')).data}catch(e){error.value=errorMessage(e)}}
async function save(){try{await api.post('/users',form.value);dialog.value=false;form.value={firstName:'',lastName:'',email:'',password:'',role:'RECEPTIONIST',status:'ACTIVE'};await load()}catch(e){error.value=errorMessage(e)}}
async function status(user:User){try{await api.patch(`/users/${user._id}/status`,{status:(user.status||'ACTIVE')==='ACTIVE'?'INACTIVE':'ACTIVE'});await load()}catch(e){error.value=errorMessage(e)}}
onMounted(load);
</script>
<template><div class="page-head"><div><h1>Usuarios</h1><p>Administra el acceso del equipo al taller.</p></div><v-btn color="accent" prepend-icon="mdi-account-plus" @click="dialog=true">Nuevo usuario</v-btn></div><v-alert v-if="error" type="error" closable @click:close="error=''">{{error}}</v-alert><v-card class="table-surface"><v-card-text><v-text-field v-model="query" prepend-inner-icon="mdi-magnify" label="Buscar por nombre o correo" variant="outlined" density="compact" max-width="360"/><v-table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Último acceso</th><th/></tr></thead><tbody><tr v-for="u in filtered" :key="u._id"><td>{{`${u.firstName||u.name||''} ${u.lastName||''}`}}</td><td>{{u.email}}</td><td><v-chip size="small">{{u.role}}</v-chip></td><td><v-chip size="small" :color="(u.status||'ACTIVE')==='ACTIVE'?'success':'secondary'">{{u.status||'ACTIVE'}}</v-chip></td><td>{{u.lastLoginAt?new Date(u.lastLoginAt).toLocaleDateString():'—'}}</td><td><v-btn v-if="u.role!=='OWNER'" size="small" variant="text" @click="status(u)">{{(u.status||'ACTIVE')==='ACTIVE'?'Desactivar':'Activar'}}</v-btn></td></tr></tbody></v-table></v-card-text></v-card><v-dialog v-model="dialog" max-width="620"><v-card title="Nuevo usuario"><v-card-text><h3>Información personal</h3><v-row><v-col><v-text-field v-model="form.firstName" label="Nombre"/></v-col><v-col><v-text-field v-model="form.lastName" label="Apellidos"/></v-col></v-row><v-text-field v-model="form.email" label="Correo" type="email"/><h3>Acceso</h3><v-select v-model="form.role" :items="[{title:'Administrador',value:'ADMIN'},{title:'Recepcionista',value:'RECEPTIONIST'}]" label="Rol"/><v-select v-model="form.status" :items="['ACTIVE','INACTIVE']" label="Estado"/><h3>Seguridad</h3><v-text-field v-model="form.password" label="Contraseña temporal" type="password"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">Cancelar</v-btn><v-btn color="accent" @click="save">Crear usuario</v-btn></v-card-actions></v-card></v-dialog></template>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.page-head h1{font-size:28px;margin:0}.page-head p{color:#667085;margin:5px 0 0}.table-surface{border:1px solid #E4E7EC;box-shadow:none;border-radius:10px}</style>
